function pickEveningMessage(state, moodId) {
  const todayFacts = state.facts.filter(f => f.date === state.currentDate && f.kind !== 'habitStep');
  const todayMins = state.timeLogs.filter(t => t.date === state.currentDate).reduce((s, t) => s + (Number(t.minutes) || 0), 0);
  let pool = EVENING_GROUPS.small;
  if (moodId === 'gentle' || (todayFacts.length === 0 && todayMins === 0)) {
    pool = EVENING_GROUPS.rest.concat(EVENING_EXTRA.slice(0, 7));
  } else if (todayFacts.some(f => f.kind === 'quest')) {
    pool = EVENING_GROUPS.progress;
  } else if (todayFacts.length >= 4) {
    pool = EVENING_GROUPS.full;
  } else if (todayFacts.some(f => f.kind === 'habit') || todayMins > 0) {
    pool = EVENING_GROUPS.habit.concat(EVENING_EXTRA.slice(7));
  }
  const seed = state.currentDate.split('').reduce((acc, ch) => acc + ch.charCodeAt(0), state.reflections.length + todayFacts.length + todayMins);
  return pool[seed % pool.length];
}

